            "question": "Thực hiện phép tính và rút gọn biểu thức sau:\\n$$A = \\left(\\frac{x + 2}{x - 2} - \\frac{x - 2}{x + 2}\\right) : \\frac{8x}{x^2 - 4}$$ (với $x \\ne \\pm 2, x \\ne 0$).",
            "rubric": "a) Quy đồng mẫu số vế trong ngoặc (0.5đ).\\nb) Biến đổi tử thức $4 \\cdot 2x$ và nhân nghịch đảo (0.25đ).\\nc) Rút gọn triệt để ra kết quả $A = 1$ (0.25đ).",
            "modelSolution": "Quy đồng mẫu vế trong ngoặc ta được:\\n$$A = \\frac{(x + 2)^2 - (x - 2)^2}{(x - 2)(x + 2)} \\cdot \\frac{x^2 - 4}{8x} = \\frac{8x}{x^2 - 4} \\cdot \\frac{x^2 - 4}{8x} = 1.$$"
