            "question": "Thực hiện phép tính và rút gọn biểu thức sau:\\n$$A = \\left(\\frac{x + 1}{x - 1} - \\frac{x - 1}{x + 1}\\right) : \\frac{4x}{x^2 - 1}$$ (với $x \\ne \\pm 1, x \\ne 0$).",
            "rubric": "a) Quy đồng mẫu số vế trong ngoặc (0.5đ).\\nb) Biến đổi tử thức $4 \\cdot 1x$ và nhân nghịch đảo (0.25đ).\\nc) Rút gọn triệt để ra kết quả $A = 1$ (0.25đ).",
            "modelSolution": "Quy đồng mẫu vế trong ngoặc ta được:\\n$$A = \\frac{(x + 1)^2 - (x - 1)^2}{(x - 1)(x + 1)} \\cdot \\frac{x^2 - 1}{4x} = \\frac{4x}{x^2 - 1} \\cdot \\frac{x^2 - 1}{4x} = 1.$$"
