            "rubric": "a) Gọi năng suất dự định và số ngày dự định, đặt điều kiện (0.25đ).\nb) Lập hệ phương trình hoặc phương trình theo giả thiết (0.50đ).\nc) Giải hệ và kết luận chiều dài đoạn đường (0.25đ).",
            "modelSolution": "Gọi năng suất làm việc mỗi ngày là $x$ (m/ngày) và số ngày hoàn thành là $y$ (ngày) ($x > 5, y > 2$). Chiều dài đoạn đường là $xy$.\nTheo bài ra ta có hệ phương trình:\n$$\\begin{cases} (x + 5)(y - 2) = xy \\\\ (x - 5)(y + 3) = xy \\end{cases} \\Leftrightarrow \\begin{cases} -2x + 5y = 10 \\\\ 3x - 5y = 15 \\end{cases} \\Leftrightarrow \\begin{cases} x = 25 \\\\ y = 12 \\end{cases}$$\nChiều dài đoạn đường là $25 \\times 12 = 300\\text{ m}$."
