            "level": "Thông hiểu",
            "points": 1.0,
            "question": "Thực hiện phép tính và rút gọn biểu thức sau:\\n$$A = \\left(\\frac{x + 3}{x - 3} - \\frac{x - 3}{x + 3}\\right) : \\frac{12x}{x^2 - 9}$$ (với $x \\ne \\pm 3, x \\ne 0$).",
            "rubric": "a) Quy đồng mẫu số vế trong ngoặc (0.5đ).\\nb) Biến đổi tử thức $4 \\cdot 3x$ và nhân nghịch đảo (0.25đ).\\nc) Rút gọn triệt để ra kết quả $A = 1$ (0.25đ).",
            "modelSolution": "Quy đồng mẫu vế trong ngoặc ta được:\\n$$A = \\frac{(x + 3)^2 - (x - 3)^2}{(x - 3)(x + 3)} \\cdot \\frac{x^2 - 9}{12x} = \\frac{12x}{x^2 - 9} \\cdot \\frac{x^2 - 9}{12x} = 1.$$"
